From 064ea5b4fea78917d2eba803e97c7bf5a7785f85 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:06:33 +0100
Subject: [PATCH] idle_inhibition: ignore idle inhibitors while the screen is
 locked

A window inhibiting idle, like a browser playing a video, kept the
screen on behind the lock screen, where it can't be seen. Stop honoring
idle inhibitors while locked, except those of the lock screen itself.

BUG: 509688
---
 src/idle_inhibition.cpp | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/src/idle_inhibition.cpp b/src/idle_inhibition.cpp
index 8923a5915d..37b23ad425 100644
--- a/src/idle_inhibition.cpp
+++ b/src/idle_inhibition.cpp
@@ -11,6 +11,7 @@
 #include "input.h"
 #include "virtualdesktops.h"
 #include "wayland/surface.h"
+#include "wayland_server.h"
 #include "window.h"
 #include "workspace.h"

@@ -74,7 +75,7 @@ void IdleInhibition::update(Window *client)

     // TODO: Don't honor the idle inhibitor object if the shell client is not
     // on the current activity (currently, activities are not supported).
-    const bool visible = client->isShown() && client->isOnCurrentDesktop();
+    const bool visible = client->isShown() && client->isOnCurrentDesktop() && (!waylandServer()->isScreenLocked() || client->isLockScreen());
     if (visible && client->surface() && client->surface()->inhibitsIdle()) {
         inhibit(client);
     } else {
@@ -86,6 +87,7 @@ void IdleInhibition::slotWorkspaceCreated()
 {
     connect(workspace(), &Workspace::windowAdded, this, &IdleInhibition::registerClient);
     connect(workspace(), &Workspace::currentDesktopChanged, this, &IdleInhibition::slotDesktopChanged);
+    connect(waylandServer(), &WaylandServer::lockStateChanged, this, &IdleInhibition::slotDesktopChanged);
 }

 void IdleInhibition::slotDesktopChanged()
